extends Node
class_name VerticalSliceDirector

signal objective_changed(text: String)
signal stage_changed(stage_id: String)
signal slice_completed

const STAGES := ["water", "taxi", "job", "port", "complete"]
const OBJECTIVES := {
    "water": "FIRST SHIFT · اشري ماء من الحانوت",
    "taxi": "FIRST SHIFT · اركب تاكسي تونس الأصفر",
    "job": "FIRST SHIFT · امشِ لمكتب الخدمة وخذ خدمة",
    "port": "FIRST SHIFT · سوق بالتاكسي للميناء وسلم المشوار",
    "complete": "FIRST SHIFT · تمت الجولة التجريبية بنجاح"
}
const PORT_ARRIVAL_RADIUS := 7.5
const GUIDANCE_REFRESH_SECONDS := 0.25

var stage := "water"
var _water: WaterVendor
var _taxi: ArcadeVehicle
var _job: JobBoard
var _port: VerticalSliceCheckpoint
var _player: PlayerController
var _finished := false
var _guidance_elapsed := 0.0
var _beacon: Node3D
var _beacon_ring: MeshInstance3D
var _beacon_label: Label3D

func configure(water: WaterVendor, taxi: ArcadeVehicle, job: JobBoard, port: VerticalSliceCheckpoint, player: PlayerController = null) -> void:
    _water = water
    _taxi = taxi
    _job = job
    _port = port
    _player = player
    if _water != null and not _water.interacted.is_connected(_on_water_interacted):
        _water.interacted.connect(_on_water_interacted)
    if _taxi != null and not _taxi.driver_entered.is_connected(_on_taxi_entered):
        _taxi.driver_entered.connect(_on_taxi_entered)
    if _job != null and not _job.interacted.is_connected(_on_job_interacted):
        _job.interacted.connect(_on_job_interacted)
    if _port != null and not _port.interacted.is_connected(_on_port_interacted):
        _port.interacted.connect(_on_port_interacted)
    _build_beacon()
    _sync_beacon()
    _emit_objective()
    set_process(true)

func _process(delta: float) -> void:
    if _finished:
        return
    _guidance_elapsed += delta
    if stage == "port" and _taxi != null and _port != null and _taxi.driver != null:
        if _taxi.global_position.distance_to(_port.global_position) <= PORT_ARRIVAL_RADIUS:
            _complete_slice("taxi_arrival")
            return
    if _guidance_elapsed >= GUIDANCE_REFRESH_SECONDS:
        _guidance_elapsed = 0.0
        _emit_objective()

func _on_water_interacted(_actor: Node) -> void:
    if stage == "water":
        _advance("taxi")

func _on_taxi_entered(_driver: PlayerController) -> void:
    if stage == "taxi":
        _advance("job")

func _on_job_interacted(_actor: Node) -> void:
    if stage == "job":
        _advance("port")

func _on_port_interacted(_actor: Node) -> void:
    if stage != "port" or _finished:
        return
    # On-foot completion is accepted only if the mission taxi was actually brought to the port.
    if _taxi == null or _port == null:
        return
    if _taxi.global_position.distance_to(_port.global_position) > PORT_ARRIVAL_RADIUS:
        RuntimeDiagnostics.record_event("vertical_slice_port_rejected", {"reason": "taxi_not_at_port"})
        _emit_objective()
        return
    _complete_slice("on_foot_with_taxi")

func _complete_slice(completion_mode: String) -> void:
    if _finished:
        return
    _finished = true
    GameState.add_money(25.0)
    GameState.set_stat("mood", GameState.mood + 10.0)
    _advance("complete")
    slice_completed.emit()
    RuntimeDiagnostics.record_event("vertical_slice_completed", {
        "reward": 25.0,
        "completion_mode": completion_mode,
        "vehicle_id": _taxi.vehicle_id if _taxi != null else ""
    })

func _advance(next_stage: String) -> void:
    if not STAGES.has(next_stage):
        return
    stage = next_stage
    stage_changed.emit(stage)
    _sync_beacon()
    _emit_objective()
    RuntimeDiagnostics.record_event("vertical_slice_stage", {"stage": stage})

func _emit_objective() -> void:
    var text := str(OBJECTIVES.get(stage, stage))
    var target := _target_for_stage()
    var actor := _guidance_actor()
    if target != null and actor != null and stage != "complete":
        var distance := actor.global_position.distance_to(target.global_position)
        text += " · %d م" % int(round(distance))
    objective_changed.emit(text)

func current_objective() -> String:
    var text := str(OBJECTIVES.get(stage, stage))
    var target := _target_for_stage()
    var actor := _guidance_actor()
    if target != null and actor != null and stage != "complete":
        text += " · %d م" % int(round(actor.global_position.distance_to(target.global_position)))
    return text

func is_completed() -> bool:
    return _finished and stage == "complete"

func serialize_runtime() -> Dictionary:
    return {"stage": stage, "finished": _finished}

func restore_runtime(data: Dictionary) -> void:
    var candidate := str(data.get("stage", "water"))
    if STAGES.has(candidate):
        stage = candidate
    _finished = bool(data.get("finished", stage == "complete"))
    if _finished:
        stage = "complete"
    _sync_beacon()
    _emit_objective()

func _target_for_stage() -> Node3D:
    match stage:
        "water": return _water
        "taxi": return _taxi
        "job": return _job
        "port": return _port
        _: return null

func _guidance_actor() -> Node3D:
    if _taxi != null and _taxi.driver != null:
        return _taxi
    return _player

func _build_beacon() -> void:
    if _beacon != null:
        return
    _beacon = Node3D.new()
    _beacon.name = "FirstShiftObjectiveBeacon"
    add_child(_beacon)

    _beacon_ring = MeshInstance3D.new()
    var torus := TorusMesh.new()
    torus.inner_radius = 1.45
    torus.outer_radius = 1.8
    _beacon_ring.mesh = torus
    _beacon_ring.rotation_degrees.x = 90.0
    var material := StandardMaterial3D.new()
    material.albedo_color = Color("#ffd447")
    material.emission_enabled = true
    material.emission = Color("#8f6500")
    material.emission_energy_multiplier = 1.8
    _beacon_ring.material_override = material
    _beacon.add_child(_beacon_ring)

    _beacon_label = Label3D.new()
    _beacon_label.text = "FIRST SHIFT"
    _beacon_label.position = Vector3(0, 2.5, 0)
    _beacon_label.font_size = 52
    _beacon_label.pixel_size = 0.006
    _beacon_label.outline_size = 10
    _beacon_label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
    _beacon.add_child(_beacon_label)

func _sync_beacon() -> void:
    if _beacon == null:
        return
    var target := _target_for_stage()
    _beacon.visible = target != null and stage != "complete"
    if target != null:
        _beacon.global_position = target.global_position + Vector3(0, 0.25, 0)

extends Node
class_name BlackoutManager

@export var interval_seconds := 45.0
@export var duration_seconds := 8.0

var timer := 0.0
var blackout_left := 0.0

func _process(delta: float) -> void:
    if blackout_left > 0.0:
        blackout_left -= delta
        if blackout_left <= 0.0:
            GameState.set_blackout(false)
        return
    timer += delta
    if timer >= interval_seconds:
        timer = 0.0
        blackout_left = duration_seconds
        GameState.set_blackout(true)
        if GameState.missions.get("survive_blackout") == "active":
            get_tree().call_group("mission_manager", "complete", "survive_blackout")

extends Node3D
class_name PopulationSpawner

@export var pedestrian_count := 24
@export var traffic_count := 10

var road_graph = null
var sidewalk_graph = null
var traffic_coordinator = null
var pedestrian_palette := [
    Color("#2d3136"), Color("#6c4f3c"), Color("#6d6f62"),
    Color("#1f3951"), Color("#7a6147")
]

func _ready() -> void:
    add_to_group("population_spawner")

func configure_road_graph(graph) -> void:
    road_graph = graph
    sidewalk_graph = SidewalkGraph.new()
    sidewalk_graph.build_from_road_graph(graph)

func configure_traffic_coordinator(value) -> void:
    traffic_coordinator = value

func spawn_all() -> void:
    _spawn_pedestrians()
    _spawn_traffic()

func _spawn_pedestrians() -> void:
    for i in range(pedestrian_count):
        var p := PedestrianAgent.new()
        p.name = "Pedestrian_%02d" % i
        p.walk_speed = 1.65 + float(i % 5) * 0.18
        p.add_to_group("hayat_pedestrian")
        p.position = Vector3(-80 + (i%9)*20, 1.0, -88 + (i/9)*176)
        add_child(p)
        if sidewalk_graph != null and not sidewalk_graph.nodes.is_empty():
            var start = sidewalk_graph.closest_node(p.position)
            var route = sidewalk_graph.random_walk(start, 8 + (i % 7), p.rng)
            if route.size() > 1:
                p.position = route[0] + Vector3(0, 1.0, 0)
                p.set_route(route)
        elif road_graph != null and not road_graph.nodes.is_empty():
            var road_start = road_graph.closest_node(p.position)
            var fallback_route = road_graph.random_walk(road_start, 8 + (i % 7), p.rng)
            if fallback_route.size() > 1:
                p.position = fallback_route[0] + Vector3(0, 1.0, 0)
                p.set_route(fallback_route)
        var col := CollisionShape3D.new()
        var cap := CapsuleShape3D.new()
        cap.radius = 0.32
        cap.height = 1.5
        col.shape = cap
        col.position.y = 0.75
        p.add_child(col)
        var body := PlayerVisualFactory.build()
        body.name = "CitizenVisual"
        body.scale = Vector3(0.88, 0.88, 0.88)
        p.add_child(body)
        if traffic_coordinator != null:
            p.configure_traffic_coordinator(traffic_coordinator)

func _spawn_traffic() -> void:
    var routes := [
        [Vector3(-95,0.7,-55),Vector3(95,0.7,-55),Vector3(95,0.7,-45),Vector3(-95,0.7,-45)],
        [Vector3(95,0.7,55),Vector3(-95,0.7,55),Vector3(-95,0.7,45),Vector3(95,0.7,45)],
        [Vector3(-55,0.7,-95),Vector3(-55,0.7,95),Vector3(-45,0.7,95),Vector3(-45,0.7,-95)],
        [Vector3(55,0.7,95),Vector3(55,0.7,-95),Vector3(45,0.7,-95),Vector3(45,0.7,95)]
    ]
    for i in range(traffic_count):
        var car := TrafficVehicle.new()
        car.name = "Traffic_%02d" % i
        car.acceleration = 6.5 + float(i % 4) * 0.75
        car.add_to_group("hayat_traffic")
        var route: Array[Vector3] = []
        for point in routes[i % routes.size()]:
            route.append(Vector3(point))
        if road_graph != null and not road_graph.nodes.is_empty():
            var start = road_graph.closest_node(route[0])
            var graph_route = road_graph.random_walk(start, 12 + (i % 9), RandomNumberGenerator.new())
            if graph_route.size() > 2:
                route.clear()
                for point in graph_route:
                    route.append(Vector3(point))
        car.lane_points = route
        car.position = route[i % route.size()]
        car.cruise_speed = 7.0 + (i % 3) * 1.4
        add_child(car)
        if traffic_coordinator != null:
            car.configure_coordinator(traffic_coordinator)
        var col := CollisionShape3D.new()
        var sh := BoxShape3D.new()
        sh.size = Vector3(1.8,1.2,4.1)
        col.shape = sh
        col.position.y = 0.6
        car.add_child(col)
        var vehicle_ids := ["taxi_01", "louage_01", "pickup_01", "pickup_404"]
        var body := VehicleVisualFactory.build(vehicle_ids[i % vehicle_ids.size()])
        body.name = "TrafficVisual"
        body.scale = Vector3(0.92, 0.92, 0.92)
        car.add_child(body)


func apply_population_budget(pedestrian_budget: int, traffic_budget: int) -> void:
    var peds := get_tree().get_nodes_in_group("hayat_pedestrian")
    for i in range(peds.size()):
        var node: Node = peds[i]
        var active := i < pedestrian_budget
        node.process_mode = Node.PROCESS_MODE_INHERIT if active else Node.PROCESS_MODE_DISABLED
        if node is Node3D:
            (node as Node3D).visible = active

    var cars := get_tree().get_nodes_in_group("hayat_traffic")
    for i in range(cars.size()):
        var node: Node = cars[i]
        var active := i < traffic_budget
        node.process_mode = Node.PROCESS_MODE_INHERIT if active else Node.PROCESS_MODE_DISABLED
        if node is Node3D:
            (node as Node3D).visible = active
